window.toggleSidebar=function(){const s=document.getElementById('sidebar');if(s)s.classList.toggle('open');};
document.addEventListener('click',function(e){const s=document.getElementById('sidebar');if(!s||window.innerWidth>900)return;if(!s.contains(e.target)&&!e.target.closest('.ref-mobile-menu'))s.classList.remove('open');});
window.awadVoice={listen:function(){return new Promise((resolve,reject)=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){reject('unsupported');return;}const r=new SR();r.lang='ar-YE';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>resolve(e.results?.[0]?.[0]?.transcript||'');r.onerror=e=>reject(e.error||'speech-error');r.onend=()=>{};try{r.start();}catch(e){reject(e);}});}};
let qatFarmInstallPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();qatFarmInstallPrompt=e;});window.installQatFarmApp=async function(){if(!qatFarmInstallPrompt)return false;qatFarmInstallPrompt.prompt();const r=await qatFarmInstallPrompt.userChoice;return r.outcome==='accepted';};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js').catch(()=>{}));
